Widget buildWeekDatePicker(DateTime selectedDate, DateTime firstAllowedDate, DateTime lastAllowedDate, ValueChanged<DatePeriod> onNewSelected){
  final styles = DatePickerRangeStyles(
    selectedPeriodLastDecoration: BoxDecoration(color: Colors.red),
    selectedPeriodStartDecoration: BoxDecoration(color: Colors.green),
    selectedPeriodMiddleDecoration: BoxDecoration(color: Colors.yellow),
  );
  return WeekPicker(
    selectedDate: selectedDate,
    onChanged: onNewSelected,
    firstDate: firstAllowedDate,
    lastDate: lastAllowedDate,
    datePickerStyles: styles,
  );
}
